using System;using System.Collections.Generic;using System.IO;using System.Linq;using MySimulator.Rebuild;
// AI lap matrix: every (track, car) pair runs a headless Race for up to 400 simulated seconds; checks finiteness, progress and lap completion.
class P{static int Main(string[] a){if(a.Length>0&&a[0]=="pitdist"){PitDist.Run();return 0;}if(a.Length>0&&a[0]=="pit"){PitProbe.Run(int.Parse(a[1]),int.Parse(a[2]));return 0;}if(a.Length>0&&a[0]=="corner"){CornerProbe.Run(int.Parse(a[1]),float.Parse(a[2],System.Globalization.CultureInfo.InvariantCulture),float.Parse(a[3],System.Globalization.CultureInfo.InvariantCulture));return 0;}if(a.Length>0&&a[0]=="core"){CoreProbe.Run(float.Parse(a[1],System.Globalization.CultureInfo.InvariantCulture));return 0;}if(a.Length>0&&a[0]=="trace"){Trace.Run(int.Parse(a[1]),int.Parse(a[2]),float.Parse(a[3]),float.Parse(a[4]));return 0;}if(a.Length>0&&a[0]=="gate"){GateProbe.Run(int.Parse(a[1]),int.Parse(a[2]));return 0;}if(a.Length>0&&a[0]=="steptest"){StepTest.Run(int.Parse(a[1]),float.Parse(a[2],System.Globalization.CultureInfo.InvariantCulture),float.Parse(a[3],System.Globalization.CultureInfo.InvariantCulture));return 0;}if(a.Length>0&&a[0]=="widths"){Widths.Run();return 0;}if(a.Length>0&&a[0]=="starts"){StartPts.Run();return 0;}if(a.Length>0&&a[0]=="probe"){Probe.Run(int.Parse(a[1]));return 0;}int shard=int.Parse(a[0]),shards=int.Parse(a[1]);int tracks=SourceRoutes.Names.Length,cars=CarCatalog.Count;int total=0,fail=0,pass=0;var lines=new List<string>();
 for(int t=0;t<tracks;t++)for(int c=0;c<cars;c++){if((t*cars+c)%shards!=shard)continue;if(a.Length>3&&(t!=int.Parse(a[2])||c!=int.Parse(a[3])))continue;total++;string why=null;float lapTime=-1,prog=0;
  try{var r=new Race(t,1,0f);var v=r.Add("AI",false,Compound.Medium);v.carModel=c;r.countdown=0;r.started=true;v.Place(r.track,0.988f,0f);float dt=float.Parse(Environment.GetEnvironmentVariable("FRAMEDT")??"0.033333",System.Globalization.CultureInfo.InvariantCulture);int maxSteps=(int)(900f/dt);float t0=0;
   for(int i=0;i<maxSteps&&!v.finished;i++){if(Environment.GetEnvironmentVariable("STRAIGHT")!=null){v.human=true;v.input=new DriverInput(1,0,0);}r.Advance(dt);if(a.Length>3&&i>=600&&i<606)Console.WriteLine($"step{i} speed={v.speed:0.000} long={v.dbgLong:0.000} acc={v.dbgAcc:0.00} yaw={v.yawRate:0.000} hdg={v.heading:0.000} steer={v.steering:0.000}");if(a.Length>3&&i%150==0&&i<5000)Console.WriteLine($"t={i*dt:0} speed={v.speed:0.0} gear={v.gear} rpm={v.rpm:0} prog={v.progress:0.000} lat={v.lateral:0.0} steer={v.steering:0.00} in(t={v.input.throttle:0.0},b={v.input.brake:0.0}) acc={v.dbgAcc:0.00} res={v.dbgRes:0} drv={v.dbgDriveF:0} brk={v.dbgBrakeF:0} long={v.dbgLong:0.0} push={v.dbgPush:0.0000}");if(!float.IsFinite(v.position.x)||!float.IsFinite(v.position.z)||!float.IsFinite(v.speed)){why="non-finite state";break;}if(v.speed>130){why="speed>130";break;}}
   prog=v.progress;if(why==null&&v.finished&&(r.ResetCount>0||v.recoveries>0))why="assisted: resets="+r.ResetCount+" recoveries="+v.recoveries;if(why==null&&v.finished&&v.bestLap<=0)why="no valid lap (off-track during the lap)";if(why==null&&!v.finished)why="lap not finished in 900s progress="+v.progress.ToString("0.00")+" laps="+v.completedLaps+" gate="+v.nextGate+" lapElapsed="+v.lapElapsed.ToString("0")+" lastLap="+v.lastLap.ToString("0.0");lapTime=v.finishTime;}
  catch(Exception e){if(a.Length>3)Console.WriteLine(e);why="exception "+e.GetType().Name+": "+e.Message;}
  if(why==null)pass++;else fail++;lines.Add($"{{\"track\":{t},\"car\":{c},\"ok\":{(why==null?"true":"false")},\"lap\":{lapTime:0.0},\"why\":\"{why}\"}}");}
 File.WriteAllLines($"laps-{shard}.jsonl",lines);Console.WriteLine($"shard {shard}/{shards}: {total} runs, {pass} pass, {fail} fail");foreach(var l in lines.Where(x=>x.Contains("\"ok\":false")).Take(15))Console.WriteLine(l);return fail>0?1:0;}}
